require "timekeeping_relay"

RSpec.describe TimekeepingRelay::Relay do
  # "The relay marks a row sent only after a `200`, so delivery is at least once."
  it "marks nothing sent on a 409 and resends the same rows once the endpoint answers 200" do
    source = Class.new do
      attr_reader :sent_positions

      def initialize(rows)
        @rows = rows
        @sent_positions = []
      end

      def unsent_after(position, limit)
        @rows.reject { |row| @sent_positions.include?(row["outbox_position"]) }
             .select { |row| row["outbox_position"] > position }
             .sort_by { |row| row["outbox_position"] }
             .first(limit)
      end

      def mark_sent(positions)
        @sent_positions |= positions
        nil
      end
    end.new([4, 9].map { |position| { "generation" => 1, "outbox_position" => position, "entry" => { "id" => position, "company_id" => 1, "version" => 1 } } })

    endpoint = Class.new do
      attr_reader :batches

      def initialize(statuses)
        @statuses = statuses
        @batches = []
      end

      def deliver(batch, idempotency_key:)
        @batches << batch
        size = (batch["snapshots"] || batch[:snapshots]).size
        status = @statuses.shift
        body = status == 200 ? { "applied" => size, "ignored" => 0 } : { "reason" => "stale_generation" }
        TimekeepingRelay::Response.new(status:, body:)
      end
    end.new([409, 200])

    relay = described_class.new(source:, endpoint:)

    expect(relay.deliver(limit: 10)).to eq(sent: 0, last_position: nil)
    expect(source.sent_positions).to be_empty

    expect(relay.deliver(limit: 10)).to eq(sent: 2, last_position: 9)
    expect(endpoint.batches[1]).to eq(endpoint.batches[0])
    expect(source.sent_positions).to contain_exactly(4, 9)
  end
end

