require "timekeeping_relay"

RSpec.describe TimekeepingRelay::Relay do
  # A crash between the 200 and the mark must leave the rows unsent, so the
  # next run sends the same body under the same key and the consumer can
  # replay its stored answer instead of applying twice.
  it "resends the identical batch under the same Idempotency-Key when marking fails after a 200" do
    source = Class.new do
      attr_reader :sent_positions

      def initialize(rows)
        @rows = rows
        @sent_positions = []
        @fail_next_mark = true
      end

      def unsent_after(position, limit)
        @rows.reject { |row| @sent_positions.include?(row["outbox_position"]) }
             .select { |row| row["outbox_position"] > position }
             .sort_by { |row| row["outbox_position"] }
             .first(limit)
      end

      def mark_sent(positions)
        if @fail_next_mark
          @fail_next_mark = false
          raise IOError, "database went away"
        end
        @sent_positions |= positions
        nil
      end
    end.new([2, 5].map { |position| { "generation" => 1, "outbox_position" => position, "entry" => { "id" => position, "company_id" => 1, "version" => 1 } } })

    endpoint = Class.new do
      attr_reader :calls

      def initialize
        @calls = []
      end

      def deliver(batch, idempotency_key:)
        @calls << { batch:, key: idempotency_key }
        size = (batch["snapshots"] || batch[:snapshots]).size
        TimekeepingRelay::Response.new(status: 200, body: { "applied" => size, "ignored" => 0 })
      end
    end.new

    relay = described_class.new(source:, endpoint:)

    expect { relay.deliver(limit: 10) }.to raise_error(IOError)
    expect(source.sent_positions).to be_empty

    expect(relay.deliver(limit: 10)).to eq(sent: 2, last_position: 5)
    expect(endpoint.calls.size).to eq(2)
    expect(endpoint.calls[1][:batch]).to eq(endpoint.calls[0][:batch])
    expect(endpoint.calls[1][:key]).to eq(endpoint.calls[0][:key])
    expect(source.sent_positions).to contain_exactly(2, 5)
  end
end

# frozen_string_literal: true
require "timekeeping_relay"

RSpec.describe TimekeepingRelay::Relay do
  # Positions have gaps after a rolled-back write, and a row can commit after
  # a higher one was sent. Marking a range up to last_position would lose it.
  it "marks only the delivered positions so a row committed later below them is still delivered" do
    source = Class.new do
      attr_reader :sent_positions, :mark_calls

      def initialize(rows)
        @rows = rows
        @sent_positions = []
        @mark_calls = []
      end

      def add(row)
        @rows << row
      end

      def unsent_after(position, limit)
        @rows.reject { |row| @sent_positions.include?(row["outbox_position"]) }
             .select { |row| row["outbox_position"] > position }
             .sort_by { |row| row["outbox_position"] }
             .first(limit)
      end

      def mark_sent(positions)
        @mark_calls << positions.to_a
        @sent_positions |= positions.to_a
        nil
      end
    end

    row = ->(position) { { "generation" => 1, "outbox_position" => position, "entry" => { "id" => position, "company_id" => 1, "version" => 1 } } }
    outbox = source.new([12, 3, 7].map(&row))

    endpoint = Class.new do
      attr_reader :positions_posted

      def initialize
        @positions_posted = []
      end

      def deliver(batch, idempotency_key:)
        snapshots = batch["snapshots"] || batch[:snapshots]
        @positions_posted << snapshots.map { |item| item["outbox_position"] || item[:outbox_position] }
        TimekeepingRelay::Response.new(status: 200, body: { "applied" => snapshots.size, "ignored" => 0 })
      end
    end.new

    relay = described_class.new(source: outbox, endpoint:)

    expect(relay.deliver(limit: 10)).to eq(sent: 3, last_position: 12)
    expect(outbox.mark_calls).to eq([[3, 7, 12]])

    outbox.add(row.call(5))
    expect(relay.deliver(limit: 10)).to eq(sent: 1, last_position: 5)
    expect(endpoint.positions_posted).to eq([[3, 7, 12], [5]])
    expect(outbox.sent_positions).to contain_exactly(3, 5, 7, 12)
  end
end

