require "timekeeping_relay"

RSpec.describe TimekeepingRelay::Relay do
  it "posts nothing on a later deliver once every row was marked sent" do
    source = Class.new do
      def initialize(rows)
        @rows = rows
        @sent_positions = []
      end

      def unsent_after(position, limit)
        @rows.reject { |row| @sent_positions.include?(row["outbox_position"]) }
             .select { |row| row["outbox_position"] > position }
             .sort_by { |row| row["outbox_position"] }
             .first(limit)
      end

      def mark_sent(positions)
        @sent_positions |= positions.to_a
        nil
      end
    end.new([1, 2, 3].map { |position| { "generation" => 1, "outbox_position" => position, "entry" => { "id" => position, "company_id" => 1, "version" => 1 } } })

    endpoint = Class.new do
      attr_reader :post_count

      def initialize
        @post_count = 0
      end

      def deliver(batch, idempotency_key:)
        @post_count += 1
        size = (batch["snapshots"] || batch[:snapshots]).size
        TimekeepingRelay::Response.new(status: 200, body: { "applied" => size, "ignored" => 0 })
      end
    end.new

    relay = described_class.new(source:, endpoint:)

    expect(relay.deliver(limit: 2)).to eq(sent: 3, last_position: 3)
    posts_after_first_run = endpoint.post_count

    expect(relay.deliver(limit: 2)).to eq(sent: 0, last_position: nil)
    expect(endpoint.post_count).to eq(posts_after_first_run)
  end
end
